"use strict";

// The same defect on an anonymous class EXPRESSION: no class binding, no
// class NAME, no elements, and no `static` token anywhere in the file.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

// A `const`-bound ARROW with a CONCISE body -- the body IS the returned
// value, so the returned value is an object literal.
const makeConfig = () => ({ mode: "fast" });

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  const Mode = class extends makeConfig() {};
  void Mode;
}

module.exports = safeOp;
